<script>(function(){const a=document.getElementById('ebp-main'),b=document.getElementById('ebp-off'),c=document.getElementById('ebp-total'),d=document.getElementById('ebp-ref-discount'),e=document.getElementById('ebp-extra'),f=document.getElementById('ebp-ref-total'),n=document.getElementById('ebp-fee-note');function update(){let x=Number(a.value)||0,y=Number(b.value)||0,z=Number(d.value)||0,fee=Number(e.value)||0,normal=Math.max(0,x-y);c.textContent='Final Package Price: ৳'+normal.toFixed(2);f.textContent='Referral Buyer Preview: ৳'+Math.max(0,normal-z+fee).toFixed(2);n.required=fee>0;}[a,b,d,e].forEach(v=>v.addEventListener('input',update));update()})();</script>
